<?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="page-heading"><div><p class="eyebrow"><?= e(t('YOUR DEVICES AND SERVICES')) ?></p><h1><?= e(t('Connections & automation')) ?></h1><p class="muted"><?= e(t('Every connection starts paused. Scheduled jobs run while LifeOS is running. Email and calendar adapters use your configured Python 3 executable.')) ?></p></div></div>
<form method="post" action="/connectivity/config" class="stack"><?= csrf_field() ?>
<section class="card"><h2><?= e(t('Encrypted external backups')) ?></h2><p><?= e(t('Choose a connected USB folder or a locally synced OneDrive/Drive folder. Keep the recovery passphrase somewhere safe. Credentials are encrypted with a device key kept outside backups; restoring on another device requires re-entering them.')) ?></p><label class="checkbox-label"><input type="checkbox" name="backup_enabled" value="1" <?= $config['backup_enabled'] ? 'checked' : '' ?>><?= e(t('Enable daily external backup')) ?></label><div class="form-grid"><label><?= e(t('Destination folder')) ?><input name="backup_destination" value="<?= e($config['backup_destination']) ?>" placeholder="D:\LifeOS backups"></label><label><?= e(t('Local backup time')) ?><input type="time" name="backup_time" value="<?= e($config['backup_time']) ?>"></label><label><?= e(t('Backups to keep')) ?><input type="number" name="backup_keep" min="2" max="90" value="<?= e($config['backup_keep']) ?>"></label><label><?= e(t('Recovery passphrase (blank keeps existing)')) ?><input type="password" name="backup_passphrase" minlength="12" autocomplete="new-password"></label></div><?php if ($config['backup_enabled'] && (Db::setting('connection_backup_success')==='' || strtotime(Db::setting('connection_backup_success'))<time()-172800)): ?><p class="notice" role="status"><?= e(t('No verified external backup in the last 48 hours. Check the destination and run a backup.')) ?></p><?php endif; ?><p><?= e(t('Last verified backup:')) ?> <?= e(Db::setting('connection_backup_success','None yet')) ?><?= e(t('. Failed attempts appear in history. A disconnected drive is retried on the next scheduled day or through Back up now.')) ?></p></section>
<section class="card"><h2><?= e(t('Email → task inbox')) ?></h2><p><?= e(t('Polling uses verified TLS, reads matching messages without marking them read, and creates reviewable previews. Accept each email to create one task. Use an app password where your provider supports it.')) ?></p><label class="checkbox-label"><input type="checkbox" name="mail_enabled" value="1" <?= $config['mail_enabled'] ? 'checked' : '' ?>><?= e(t('Enable filtered IMAP polling')) ?></label><div class="form-grid"><?php foreach (['mail_host'=>t('IMAP host'),'mail_user'=>t('Username'),'mail_folder'=>t('Mailbox'),'mail_sender'=>t('Sender contains (optional)'),'mail_subject'=>t('Subject contains (required)'),'python'=>t('Python 3 executable path')] as $key=>$label): ?><label><?= e(t($label)) ?><input name="<?= e($key) ?>" value="<?= e($config[$key]) ?>"></label><?php endforeach; ?><label><?= e(t('TLS port')) ?><input type="number" name="mail_port" value="<?= e($config['mail_port']) ?>" min="1" max="65535"></label><label><?= e(t('Poll interval (minutes)')) ?><input type="number" name="mail_interval" value="<?= e($config['mail_interval']) ?>" min="5" max="1440"></label><label><?= e(t('App password (blank keeps existing)')) ?><input type="password" name="mail_password" autocomplete="new-password"></label></div></section>
<section class="card"><h2><?= e(t('Google / Outlook calendar')) ?></h2><p><?= e(t('Register your own provider app and authorize calendar access. Use scripts/authorize_calendar.py to sign in through your system browser, then save its refresh token and your client ID below. Access tokens refresh automatically. A manually supplied access token also works until it expires. Sync covers timed events from 30 days ago through the next year. All-day events are counted and skipped. Simultaneous edits are preserved as conflicts in history; deletions are retained locally for review.')) ?></p><label class="checkbox-label"><input type="checkbox" name="calendar_enabled" value="1" <?= $config['calendar_enabled'] ? 'checked' : '' ?>><?= e(t('Enable calendar sync every 15 minutes')) ?></label><div class="form-grid"><label><?= e(t('Provider')) ?><select name="calendar_provider"><option value="google" <?= $config['calendar_provider']==='google' ? 'selected' : '' ?>><?= e(t('Google Calendar')) ?></option><option value="outlook" <?= $config['calendar_provider']==='outlook' ? 'selected' : '' ?>><?= e(t('Outlook / Microsoft Graph')) ?></option></select></label><label><?= e(t('Calendar ID (primary = default)')) ?><input name="calendar_id" value="<?= e($config['calendar_id']) ?>"></label><label><?= e(t('OAuth client ID')) ?><input name="calendar_client_id" value="<?= e($config['calendar_client_id']) ?>"></label><label><?= e(t('Microsoft tenant (common for personal accounts)')) ?><input name="calendar_tenant" value="<?= e($config['calendar_tenant']) ?>"></label><label><?= e(t('OAuth client secret (Google desktop client, blank keeps existing)')) ?><input type="password" name="calendar_client_secret" autocomplete="new-password"></label><label><?= e(t('OAuth refresh token (blank keeps existing)')) ?><input type="password" name="calendar_refresh_token" autocomplete="new-password"></label><label><?= e(t('OAuth access token (optional, blank keeps existing)')) ?><input type="password" name="calendar_access_token" autocomplete="new-password"></label></div><label class="checkbox-label"><input type="checkbox" name="calendar_push" value="1" <?= $config['calendar_push'] ? 'checked' : '' ?>><?= e(t('Also publish new and edited scheduled appointments to this calendar')) ?></label><p class="muted"><?= e(t('Publishing creates personal events without attendees or invitations. Remote conditional updates protect concurrent edits. Remote cancellations update linked appointments; local cancellations and deletions are never sent automatically.')) ?></p></section>
<section class="card"><h2><?= e(t('Application time tracking')) ?></h2><p><?= e(t('Run the optional Windows tracker script with a time.write API token after enabling capture here. It records process names, category and elapsed seconds. Window titles and keystrokes are never recorded. Pause from the tracker terminal or disable here at any time.')) ?></p><label class="checkbox-label"><input type="checkbox" name="tracking_enabled" value="1" <?= $config['tracking_enabled'] ? 'checked' : '' ?>><?= e(t('Allow application time capture')) ?></label><div class="form-grid"><label><?= e(t('Excluded process names (comma-separated)')) ?><input name="tracking_exclusions" value="<?= e($config['tracking_exclusions']) ?>"></label><label><?= e(t('Retention days')) ?><input type="number" name="tracking_retention" min="1" max="365" value="<?= e($config['tracking_retention']) ?>"></label></div></section><button><?= e(t('Save connection preferences')) ?></button></form>
<section class="card"><h2><?= e(t('Run a connection')) ?></h2><div class="hero-actions"><?php foreach (['backup'=>t('Back up now'),'mail/poll'=>t('Poll matching email'),'calendar/sync'=>t('Sync calendar')] as $route=>$label): ?><form method="post" action="/connectivity/<?= e($route) ?>"><?= csrf_field() ?><button class="secondary"><?= e(t($label)) ?></button></form><?php endforeach; ?><a href="/connectivity/calendar/export" class="btn secondary"><?= e(t('Export ICS calendar')) ?></a></div></section>
<section class="card"><h2><?= e(t('Import ICS')) ?></h2><p><?= e(t('Paste a calendar to review before saving. Individual timed events support UTC/TZID. Recurrence and all-day events require expansion into timed instances first.')) ?></p><form method="post" action="/connectivity/calendar/preview"><?= csrf_field() ?><label><?= e(t('ICS calendar')) ?><textarea name="ics" rows="5" maxlength="2097152" required></textarea></label><button><?= e(t('Preview import')) ?></button></form></section>
<section class="card"><h2><?= e(t('Email previews')) ?></h2><?php if (!$mail): ?><p class="muted"><?= e(t('No matching messages awaiting review.')) ?></p><?php endif; ?><?php foreach ($mail as $m): ?><article class="task-row"><div><strong><?= e($m['subject']) ?></strong><small><?= e($m['sender']) ?></small><details><summary><?= e(t('Message preview')) ?></summary><p><?= nl2br(e($m['body'])) ?></p></details></div><div class="hero-actions"><?php foreach (['accept'=>t('Create task'),'ignore'=>t('Ignore')] as $action=>$label): ?><form method="post" action="/connectivity/mail/<?= e($m['id']) ?>/<?= e($action) ?>"><?= csrf_field() ?><button class="secondary"><?= e(t($label)) ?></button></form><?php endforeach; ?></div></article><?php endforeach; ?></section>
<section class="card"><h2><?= e(t('Local API & CLI')) ?></h2><label><?= e(t('API base URL')) ?><input readonly value="<?= e('http://'.($_SERVER['HTTP_HOST'] ?? '127.0.0.1:8787')) ?>"></label><label><?= e(t('API profile ID')) ?><input readonly value="<?= e(class_exists('ProfileManager') ? ProfileManager::id() : 'default') ?>"></label><p><?= e(t('Loopback only, profile scoped, version 1. Tokens expire after 90 days and work separately from the PIN. Supported resources: GET/POST /api/v1/tasks, POST /api/v1/tasks/{id}/complete, POST /api/v1/window-time. Use scripts/lifeos_cli.py or an n8n HTTP node with Authorization: Bearer TOKEN.')) ?></p><form method="post" action="/connectivity/tokens"><?= csrf_field() ?><label><?= e(t('Token name')) ?><input name="name" required maxlength="100"></label><div class="hero-actions"><?php foreach (['tasks.read','tasks.write','time.write'] as $scope): ?><label class="checkbox-label"><input type="checkbox" name="scopes[]" value="<?= e($scope) ?>"><?= e($scope) ?></label><?php endforeach; ?></div><button><?= e(t('Create scoped token')) ?></button></form><?php foreach ($tokens as $t): ?><div class="task-row"><div><strong><?= e($t['name']) ?></strong><small><?= e($t['scopes']) ?> <?= e(t('· expires')) ?> <?= e($t['expires_at']) ?> <?= e(t('UTC')) ?></small></div><form method="post" action="/connectivity/tokens/<?= e($t['id']) ?>/revoke"><?= csrf_field() ?><button class="quiet"><?= e(t('Revoke')) ?></button></form></div><?php endforeach; ?></section>
<section class="card"><h2><?= e(t('User macros & scheduled scripts')) ?></h2><p><?= e(t('Macros can create tasks or run explicitly approved .php/.py scripts on this computer. Scripts have your user account\'s permissions. Scripts are pinned to their approved SHA-256 and stop after 20 seconds with bounded output. A failed macro may have completed earlier actions; review history before running again.')) ?></p><form method="post" action="/connectivity/macros"><?= csrf_field() ?><div class="form-grid"><label><?= e(t('Name')) ?><input name="name" required maxlength="100"></label><label><?= e(t('Daily local time')) ?><input type="time" name="run_at" value="09:00" required></label></div><label><?= e(t('Action list (JSON)')) ?><textarea name="actions" rows="4" required placeholder='[{"type":"task","title":"Daily review","due_days":0}]'></textarea></label><label class="checkbox-label"><input type="checkbox" name="trust_scripts" value="1"><?= e(t('I approve running the exact script files listed above')) ?></label><label class="checkbox-label"><input type="checkbox" name="enabled" value="1"><?= e(t('Enable daily schedule')) ?></label><button><?= e(t('Save macro')) ?></button></form><?php foreach ($macros as $m): ?><div class="task-row"><div><strong><?= e($m['name']) ?></strong><small><?= $m['enabled'] ? t('Enabled') : t('Paused') ?> · <?= e($m['run_at']) ?></small></div><div class="hero-actions"><?php foreach (['run'=>t('Run now'),'toggle'=>t('Pause / enable'),'delete'=>t('Remove')] as $action=>$label): ?><form method="post" action="/connectivity/macros/<?= e($m['id']) ?>/<?= e($action) ?>"><?= csrf_field() ?><button class="secondary"><?= e(t($label)) ?></button></form><?php endforeach; ?></div></div><?php endforeach; ?><?php foreach ($macroRuns as $run): ?><p><?= e($run['created_at'].' · '.$run['status'].' · '.$run['detail']) ?></p><?php endforeach; ?></section>
<section class="card"><h2><?= e(t('Captured application time')) ?></h2><?php foreach ($tracking as $row): ?><p><?= e($row['category'].' · '.$row['process'].' · '.round($row['seconds']/60,1).' minutes') ?></p><?php endforeach; ?><form method="post" action="/connectivity/tracking/clear"><?= csrf_field() ?><button class="quiet"><?= e(t('Delete captured time')) ?></button></form></section>
<section class="card"><h2><?= e(t('Connection history')) ?></h2><?php if (!$runs): ?><p><?= e(t('No connection attempts yet.')) ?></p><?php endif; ?><?php foreach ($runs as $run): ?><p><strong><?= e($run['kind'].' · '.$run['status']) ?></strong> <?= e($run['created_at'].' · '.$run['detail']) ?></p><?php endforeach; ?><form method="post" action="/connectivity/secrets/forget"><?= csrf_field() ?><button class="quiet"><?= e(t('Remove saved connection credentials')) ?></button></form></section>
